urn:mrr:concept-charter:01KYX5Y9WCAG2P1JXGDPKWXZ2A	1	mrr/v1alpha1	ConceptCharter	urn:mrr:practice:01KYX5Y9G3X30ZYAR23S0FE14T	2026-08-01 00:50:26.060784+02	urn:mrr:person:01KY4PZ13XBPPWVNB3H30MD02J	sha256:9cb82b328f86b22d2385a7b44d6859527d09f007782fb6b025af40422f55d298	\N	null	{"id": "urn:mrr:concept-charter:01KYX5Y9WCAG2P1JXGDPKWXZ2A", "kind": "ConceptCharter", "status": "draft", "entries": [{"term": "end-to-end research automation", "entry_id": "end-to-end-research-automation-v1", "definition": "A single system carrying a research undertaking across the whole life cycle — from forming the question or hypothesis, through designing and executing experiments or analyses, to producing a written scientific report — without a human supplying the research idea and without human intervention required at the stage boundaries.", "scope_note": "Local operationalization for this profile only. The load-bearing element is the FIRST stage: a system handed a human-authored objective, dataset or idea automates a segment of research, not the life cycle. This is deliberately stricter than colloquial 'AI scientist' usage, and the strictness is the point — the survey being examined turns on exactly that distinction."}, {"term": "demonstrates", "entry_id": "demonstrates-vs-reports-v1", "definition": "A source 'demonstrates' end-to-end research automation when it presents its OWN system executing the pipeline defined in end-to-end-research-automation-v1 and reports the result of running it. A source 'reports on' such automation when it evaluates, audits, benchmarks, or proposes governance for systems built by others, without itself running such a pipeline as its contribution.", "scope_note": "The distinction is about what the source CONTRIBUTES, not what it is about. An independent evaluation of an end-to-end system is a report on the field, not a demonstration of it — and its findings bear on whether the demonstration holds. Applied to the eight citations of the published survey, fixed before classification."}], "revision": 1, "created_at": "2026-07-31T22:50:26.060784Z", "created_by": "urn:mrr:person:01KY4PZ13XBPPWVNB3H30MD02J", "api_version": "mrr/v1alpha1", "practice_id": "urn:mrr:practice:01KYX5Y9G3X30ZYAR23S0FE14T", "content_hash": "sha256:9cb82b328f86b22d2385a7b44d6859527d09f007782fb6b025af40422f55d298"}
urn:mrr:concept-charter:01KYX5Y9WCAG2P1JXGDPKWXZ2A	2	mrr/v1alpha1	ConceptCharter	urn:mrr:practice:01KYX5Y9G3X30ZYAR23S0FE14T	2026-08-01 00:50:26.15185+02	urn:mrr:person:01KY4PZ13XBPPWVNB3H30MD02J	sha256:5ebbd649e6f72f1156393bfb68137f270a77e80c5098b6c43fef07232547f8d0	\N	null	{"id": "urn:mrr:concept-charter:01KYX5Y9WCAG2P1JXGDPKWXZ2A", "kind": "ConceptCharter", "status": "accepted", "entries": [{"term": "end-to-end research automation", "entry_id": "end-to-end-research-automation-v1", "definition": "A single system carrying a research undertaking across the whole life cycle — from forming the question or hypothesis, through designing and executing experiments or analyses, to producing a written scientific report — without a human supplying the research idea and without human intervention required at the stage boundaries.", "scope_note": "Local operationalization for this profile only. The load-bearing element is the FIRST stage: a system handed a human-authored objective, dataset or idea automates a segment of research, not the life cycle. This is deliberately stricter than colloquial 'AI scientist' usage, and the strictness is the point — the survey being examined turns on exactly that distinction."}, {"term": "demonstrates", "entry_id": "demonstrates-vs-reports-v1", "definition": "A source 'demonstrates' end-to-end research automation when it presents its OWN system executing the pipeline defined in end-to-end-research-automation-v1 and reports the result of running it. A source 'reports on' such automation when it evaluates, audits, benchmarks, or proposes governance for systems built by others, without itself running such a pipeline as its contribution.", "scope_note": "The distinction is about what the source CONTRIBUTES, not what it is about. An independent evaluation of an end-to-end system is a report on the field, not a demonstration of it — and its findings bear on whether the demonstration holds. Applied to the eight citations of the published survey, fixed before classification."}], "revision": 2, "created_at": "2026-07-31T22:50:26.151850+00:00", "created_by": "urn:mrr:person:01KY4PZ13XBPPWVNB3H30MD02J", "api_version": "mrr/v1alpha1", "practice_id": "urn:mrr:practice:01KYX5Y9G3X30ZYAR23S0FE14T", "content_hash": "sha256:5ebbd649e6f72f1156393bfb68137f270a77e80c5098b6c43fef07232547f8d0"}
