urn:mrr:evidence-matrix:01KYX5YBBHBCY5J7P33QSKRXWH	1	mrr/v1alpha1	EvidenceMatrix	urn:mrr:practice:01KYX5Y9G3X30ZYAR23S0FE14T	2026-08-01 00:50:27.570105+02	urn:mrr:person:01KY4PZ13XBPPWVNB3H30MD02J	sha256:6404eaa6f88c0f4f74e595f55a9d177bccf4c0e2118b82b4f0e7823b1d68de24	\N	null	{"id": "urn:mrr:evidence-matrix:01KYX5YBBHBCY5J7P33QSKRXWH", "kind": "EvidenceMatrix", "rows": [{"row_id": "sakana-nature", "extraction": {"classification_basis": "Abstract states the contribution as a system executing the full life cycle including idea creation — the first stage end-to-end-research-automation-v1 makes load-bearing. Its own demonstration, not a report on others'. Classified supports."}, "source_record_id": "urn:mrr:source-record:01KYX5YARDXYSDJEVE6JT3FMSP", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KYX5YASV7EGA4BF0JFZ56QR4", "verification_status": "verified", "claim_relevant_finding": "Presents its own pipeline for 'automating the entire scientific process end to end': the system creates research ideas, writes code, runs experiments, plots and analyses data, writes the entire manuscript, and performs its own peer review. A generated manuscript passed the first round of peer review at a workshop with a 70% acceptance rate."}, {"row_id": "kosmos", "extraction": {"classification_basis": "A real demonstration, but the abstract states the objective and the dataset are supplied to it. Under end-to-end-research-automation-v1 the conception stage is therefore human-supplied: this automates a long segment of research, not the life cycle. Classified qualifies, not supports."}, "source_record_id": "urn:mrr:source-record:01KYX5YATFG88EZER7189J479J", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KYX5YAW0C5NRK5RW69AK3KFX", "verification_status": "verified", "claim_relevant_finding": "Presents its own system automating data-driven discovery: given an open-ended objective AND a dataset, it runs up to 12 hours over ~200 agent rollouts, executing an average of 42,000 lines of code and reading 1,500 papers per run, before synthesizing discoveries into scientific reports."}, {"row_id": "agent-laboratory", "extraction": {"classification_basis": "Both load-bearing conditions of end-to-end-research-automation-v1 fail by the abstract's own wording: the idea is human-provided, and human guidance at each stage is a designed-in feature rather than an option. A real system, deliberately human-in-the-loop. Classified qualifies."}, "source_record_id": "urn:mrr:source-record:01KYX5YAX6QBKJ5QK0XR0ZC6GB", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KYX5YAYGFNF1YAB1Q06WMV74", "verification_status": "verified", "claim_relevant_finding": "Presents its own framework completing literature review, experimentation and report writing — but the abstract states it 'accepts a human-provided research idea' and is built for 'enabling users to provide feedback and guidance at each stage'."}, {"row_id": "independent-ai-scientist-eval", "extraction": {"classification_basis": "Contributes an evaluation of another team's system, not a demonstration — so 'reports on' per demonstrates-vs-reports-v1. Its findings bear directly against the demonstration claim it examines. Classified contradicts. Note: examines the same system as sakana-ai-scientist but is an independent author team and a separate work, so a distinct source family."}, "source_record_id": "urn:mrr:source-record:01KYX5YAZZ2AX935D729NFKK48", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KYX5YB0P79WQEQN95TXSR57K", "verification_status": "verified", "claim_relevant_finding": "An independent evaluation of the AI Scientist reporting critical shortcomings: literature reviews produced poor novelty assessments, often misclassifying established concepts as novel; 42% of experiments failed due to coding errors, while others produced flawed or misleading results."}, {"row_id": "sciintegrity-bench", "extraction": {"classification_basis": "Contributes a benchmark, not a demonstration — 'reports on' per demonstrates-vs-reports-v1. Its finding that every tested model fabricates data rather than reporting infeasibility bears against the reliability of autonomous end-to-end operation. Classified contradicts."}, "source_record_id": "urn:mrr:source-record:01KYX5YB2B5JBXGFRA0EJ3EXSJ", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KYX5YB3JQDSPY5A9JNK9EF5F", "verification_status": "verified", "claim_relevant_finding": "A benchmark of academic integrity in AI scientist systems: across 231 runs over 7 state-of-the-art LLMs the overall integrity problem rate reaches 34.2%, no model achieves zero failures, and across missing-data scenarios ALL seven models generate synthetic data rather than acknowledging infeasibility."}, {"row_id": "deeptrace", "extraction": {"classification_basis": "Contributes an audit framework and its results, not a demonstration — 'reports on' per demonstrates-vs-reports-v1. Findings bear against the trustworthiness of automated research output. Classified contradicts."}, "source_record_id": "urn:mrr:source-record:01KYX5YB4ZHFFFCVRA26Y5KAC3", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KYX5YB6GAXC50XKH55CNY2GH", "verification_status": "verified", "claim_relevant_finding": "An audit framework over eight measurable dimensions of answer text, sources and citations, applied to public generative search engines and deep-research configurations. Finds these systems frequently produce one-sided, highly confident responses on debate queries, alongside weak sourcing and confusing citation practice."}, {"row_id": "claim-level-auditability-aar", "extraction": {"classification_basis": "Contributes a standard and a perspective, neither a demonstration nor an empirical evaluation of one — 'reports on' per demonstrates-vs-reports-v1, in its governance sense. It reframes the question rather than bearing for or against a demonstration. Classified contextualizes."}, "source_record_id": "urn:mrr:source-record:01KYX5YB7KMVK124XXD778EPW3", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KYX5YB82C4P52VRH5N7SJE9S", "verification_status": "verified", "claim_relevant_finding": "A perspective arguing that as research generation becomes cheap, auditability becomes the bottleneck, and proposing the Auditable Autonomous Research (AAR) standard — a measurement framework over provenance coverage, provenance soundness, contradiction transparency and audit effort."}, {"row_id": "inspectable-ai-for-science", "extraction": {"classification_basis": "Contributes a governance paradigm and a lightweight pipeline implementing it, not a demonstration of end-to-end research automation — 'reports on' in its governance sense. Bears on how such work should be documented, not on whether it has been achieved. Classified contextualizes."}, "source_record_id": "urn:mrr:source-record:01KYX5YB9A117AT9G03Z7DV47Z", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KYX5YBA5R2NSP0XVHQJ2RDXB", "verification_status": "verified", "claim_relevant_finding": "Proposes AI as a Research Object (AI-RO), a paradigm treating AI interactions as structured, inspectable components of the research process, with model configuration, prompts and outputs recorded through interaction logs and metadata packaging."}], "status": "draft", "revision": 1, "created_at": "2026-07-31T22:50:27.570105Z", "created_by": "urn:mrr:person:01KY4PZ13XBPPWVNB3H30MD02J", "api_version": "mrr/v1alpha1", "practice_id": "urn:mrr:practice:01KYX5Y9G3X30ZYAR23S0FE14T", "protocol_id": "urn:mrr:method-protocol:01KYX5YA2Q2RG1HPZBBP47RD5G", "question_id": "urn:mrr:question-model:01KYX5Y9SCQ7T9XJ48M96700NQ", "content_hash": "sha256:6404eaa6f88c0f4f74e595f55a9d177bccf4c0e2118b82b4f0e7823b1d68de24"}
